package com.taller.gestion.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity public class WorkOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true,nullable=false) private String folio; @Column(nullable=false) private String clientName; private String clientPhone; private String vehicle; private String plates; @Column(length=2000) private String reportedProblem; @Column(length=2000) private String initialCondition; @Enumerated(EnumType.STRING) private OrderStatus status=OrderStatus.RECIBIDO; private String assignedMechanic; private LocalDateTime receivedAt=LocalDateTime.now(); private LocalDateTime promisedDeliveryAt; private BigDecimal quotedTotal; @Column(length=2000) private String customerFeedback; public Long getId(){return id;} public String getFolio(){return folio;} public void setFolio(String v){folio=v;} public String getClientName(){return clientName;} public void setClientName(String v){clientName=v;} public String getClientPhone(){return clientPhone;} public void setClientPhone(String v){clientPhone=v;} public String getVehicle(){return vehicle;} public void setVehicle(String v){vehicle=v;} public String getPlates(){return plates;} public void setPlates(String v){plates=v;} public String getReportedProblem(){return reportedProblem;} public void setReportedProblem(String v){reportedProblem=v;} public String getInitialCondition(){return initialCondition;} public void setInitialCondition(String v){initialCondition=v;} public OrderStatus getStatus(){return status;} public void setStatus(OrderStatus v){status=v;} public String getAssignedMechanic(){return assignedMechanic;} public void setAssignedMechanic(String v){assignedMechanic=v;} public LocalDateTime getPromisedDeliveryAt(){return promisedDeliveryAt;} public void setPromisedDeliveryAt(LocalDateTime v){promisedDeliveryAt=v;} public BigDecimal getQuotedTotal(){return quotedTotal;} public void setQuotedTotal(BigDecimal v){quotedTotal=v;} public String getCustomerFeedback(){return customerFeedback;} public void setCustomerFeedback(String v){customerFeedback=v;} }
